SELECT ?series WHERE {
  ?series dbo:creator dbr:Hilarie_Ross_Burton ;
          dbo:network dbr:The_WB ;
          rdf:type dbo:TelevisionSeries .
}

SELECT ?actress WHERE {
  dbr:Grace,_Replaced dbo:starring ?actress .
}

SELECT ?actress ?series WHERE {
  ?series dbo:creator dbr:Hilarie_Ross_Burton ;
          dbo:network dbr:The_WB ;
          rdf:type dbo:TelevisionSeries .
  ?episode dbo:series ?series .
  ?episode dbo:guestStar ?actress .
  VALUES ?actress { <list_of_actresses_from_Grace_Replaced> }
}

SELECT ?actor ?actorLabel WHERE {
  ?wonderWoman rdf:type wd:Q11421.   # Wonder Woman (the character)
  ?wonderWomanFilm wdt:P31 wd:Q11424;  # film
                     wdt:P364 wd:Q1860;  # language English
                     wdt:P57 ?director.
  ?wonderWomanFilm wdt:P161 ?actor.   # cast member
  ?wonderWomanFilm wdt:P577 ?releaseDate.
  FILTER(YEAR(?releaseDate) = 2017)

  ?anomalisaFilm wdt:P31 wd:Q11424;
                  wdt:P161 ?actor.
  ?anomalisaFilm wdt:P577 ?anomalisaReleaseDate.
  FILTER(YEAR(?anomalisaReleaseDate) >= 2015)

  ?fargoFilm wdt:P31 wd:Q11424;
             wdt:P1476 "Fargo"@en;
             wdt:P577 ?fargoReleaseDate.
  FILTER(?fargoReleaseDate <= ?anomalisaReleaseDate)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
} LIMIT 10

SELECT ?actor WHERE {
  ?wonderWomanMovie wdt:P31 wd:Q11424;  # instance of film
                    rdfs:label "Wonder Woman"@en;
                    wdt:P577 ?wwReleaseDate;
                    wdt:P136 wd:Q188473.  # genre action-adventure
  ?movieActing1 wdt:P161 ?actor.
  FILTER(CONTAINS(LCASE(STR(?movieActing1)), "wonder woman"))

  ?anomalisaMovie rdfs:label "Anomalisa"@en;
                  wdt:P161 ?actor;
                  wdt:P577 ?anomalisaDate.

  ?fargoFilm rdfs:label "Fargo"@en;
             wdt:P577 ?fargoPremiereDate.

  FILTER(?anomalisaDate > ?fargoPremiereDate)
} LIMIT 10

SELECT ?relientK_vocalist ?professionRelientK ?georgeThorogood ?professionThorogood WHERE {
  ?relientK_artist wdt:P31 wd:Q5;  # instance of human
                     wdt:P106 ?professionRelientK;
                     rdfs:label ?labelRelientK.
  FILTER(CONTAINS(LCASE(?labelRelientK), "relient k vocalist")).

  # Find if this artist co-wrote "Rebuild" with Jon Foreman
  ?song wdt:P31 wd:Q7366;  # instance of song
        rdfs:label "Rebuild"@en;
        wdt:P175 ?relientK_artist, ?jonForeman.

  ?jonForeman rdfs:label "Jon Foreman"@en.

  # George Thorogood profession
  ?georgeThorogood rdfs:label "George Thorogood"@en; 
                   wdt:P106 ?professionThorogood.

  FILTER(?professionRelientK = ?professionThorogood)
}
LIMIT 1

SELECT ?relientK_vocalist ?professionRelientK ?georgeThorogood ?professionThorogood WHERE {
  ?relientK_artist wdt:P31 wd:Q5;  # instance of human
                     wdt:P106 ?professionRelientK;
                     rdfs:label ?labelRelientK.
  FILTER(CONTAINS(LCASE(?labelRelientK), "relient k vocalist")).

  # Find if this artist co-wrote "Rebuild" with Jon Foreman
  ?song wdt:P31 wd:Q7366;  # instance of song
        rdfs:label "Rebuild"@en;
        wdt:P175 ?relientK_artist, ?jonForeman.

  ?jonForeman rdfs:label "Jon Foreman"@en.

  # George Thorogood profession
  ?georgeThorogood rdfs:label "George Thorogood"@en; 
                   wdt:P106 ?professionThorogood.

  FILTER(?professionRelientK = ?professionThorogood)
}
LIMIT 1

