SELECT ?player ?playerName ?birthPlace WHERE {
  VALUES ?playerName {"Angelique Kerber"}
  ?player wdt:P31 wd:Q532;        # instance of tennis player
          rdfs:label ?playerName;
          wdt:P19 ?birthPlace.
  FILTER(LANG(?playerName) = "en")
}
